import isObject from '../utils/isObject';
import set from '../utils/set';

export default <T extends FieldValues = FieldValues>(
  errors: FieldErrors<T>,
  error: Partial<Record<string, FieldError>>,
  name: InternalFieldName,
): FieldErrors<T> => {
  const existingError = get(errors, name);
  const resolverError = error[name];
  const hasNumericErrors = (value: unknown) =>
    isObject(value) && Object.keys(value).some((key) => /^\d+$/.test(key));
  const fieldArrayErrors = hasNumericErrors(existingError)
    ? hasNumericErrors(resolverError)
      ? resolverError
      : existingError
    : Array.isArray(existingError)
      ? existingError
      : convertToArrayPayload(existingError);
  set(fieldArrayErrors, ROOT_ERROR_TYPE, resolverError);
  set(errors, name, fieldArrayErrors);
  return errors;
};

